var mdlIn=false,mdlS,mdlC,mdlR,mdlOr,mdlGroup,mdlParts=[],mdlSelIdx=-1,mdlEditId=null,mdlAnimPreview='idle';
function makeShapeGeo(shape){if(shape==='sphere')return new THREE.SphereGeometry(.5,20,14);if(shape==='cylinder')return new THREE.CylinderGeometry(.5,.5,1,20);if(shape==='cone')return new THREE.ConeGeometry(.5,1,20);return new THREE.BoxGeometry(1,1,1)}
function buildModelFromDef(def){var g=new THREE.Group();if(!def||!def.parts)return g;def.parts.forEach(function(p){var mat=new THREE.MeshStandardMaterial({color:new THREE.Color(p.color||'#888'),roughness:.75});var m=new THREE.Mesh(makeShapeGeo(p.shape),mat);if(p.pos)m.position.set(p.pos[0],p.pos[1],p.pos[2]);if(p.rot)m.rotation.set(p.rot[0],p.rot[1],p.rot[2]);if(p.scale)m.scale.set(p.scale[0],p.scale[1],p.scale[2]);m.userData.role=p.role||'other';g.add(m)});return g}
function applyModelAnim(g,state,dt){if(!g||!g.userData)return;g.userData.animTime=(g.userData.animTime||0)+dt;var t=g.userData.animTime;g.children.forEach(function(m){var r=m.userData.role;if(!r)return;if(state==='idle'){m.position.y+=Math.sin(t*2+r)*.001}else if(state==='walk'){if(r==='legL'||r==='legR'){m.rotation.x=Math.sin(t*8+(r==='legL'?0:3.14))*.6}}else if(state==='run'){if(r==='legL'||r==='legR'){m.rotation.x=Math.sin(t*14+(r==='legL'?0:3.14))*1}else if(r==='head'){m.rotation.x=-.15}}else if(state==='jump'){if(r==='legL'||r==='legR')m.rotation.x=-.5;if(r==='head')m.rotation.x=-.2}else if(state==='sit'){if(r==='legL'||r==='legR')m.rotation.x=1}else if(state==='sleep'){if(r==='head')m.rotation.x=.4}else if(state==='dance'){if(r==='head')m.rotation.z=Math.sin(t*6)*.4;if(r==='legL'||r==='legR')m.rotation.x=Math.sin(t*6)*.8}else if(state==='spin'){g.rotation.y=t*4}else if(state==='backflip'){g.rotation.x=((t%2)/2)*Math.PI*2}else if(state==='wagTail'){if(r==='tail')m.rotation.y=Math.sin(t*20)*1}else if(state==='sad'){if(r==='head')m.rotation.x=.4}else if(state==='happy'){if(r==='tail')m.rotation.y=Math.sin(t*15);if(r==='head')m.rotation.z=Math.sin(t*8)*.15}else if(state==='attack'){if(r==='armL'||r==='armR')m.rotation.x=-Math.abs(Math.sin(t*12))*1.2}else if(state==='wave'){if(r==='armR')m.rotation.z=-1.5+Math.sin(t*8)*.3}else if(state==='point'){if(r==='armR'){m.rotation.x=-1.4}}})}
var _origSpawnFromData=spawnFromData;
function spawnFromDataPatched(d,grp){grp=grp||pg;if(d.type==='model'){var g=buildModelFromDef(d.def);g.position.fromArray(d.position||[0,0,0]);g.rotation.fromArray(d.rotation||[0,0,0]);g.scale.fromArray(d.scale||[1,1,1]);g.userData.type='model';g.userData.id=d.id||genId('m');g.userData.name=d.name||'Модель';g.userData.def=d.def;g.userData.script=d.script||(d.def&&d.def.script)||'';g.userData.isPet=d.def&&d.def.isPet;g.userData.animTime=0;if(grp)grp.add(g);return g}return _origSpawnFromData(d,grp)}
var _origObjToData=objToData;
function objToDataPatched(o){if(o.userData&&o.userData.type==='model'){return{id:o.userData.id,type:'model',name:o.userData.name,def:o.userData.def,script:o.userData.script,position:[o.position.x,o.position.y,o.position.z],rotation:[o.rotation.x,o.rotation.y,o.rotation.z],scale:[o.scale.x,o.scale.y,o.scale.z]}}return _origObjToData(o)}
function initMdlEditor(){var vp=document.getElementById('mdlViewport');mdlS=new THREE.Scene();mdlS.background=new THREE.Color(0x87ceeb);var w=vp.clientWidth||600,h=vp.clientHeight||500;mdlC=new THREE.PerspectiveCamera(50,w/h,.1,200);mdlC.position.set(5,5,8);mdlC.lookAt(0,2,0);mdlR=new THREE.WebGLRenderer({antialias:true});mdlR.setPixelRatio(Math.min(devicePixelRatio,2));mdlR.setSize(w,h);vp.appendChild(mdlR.domElement);mdlS.add(new THREE.HemisphereLight(0xffffff,0x555555,1));mdlS.add(new THREE.AmbientLight(0xffffff,.5));var dl=new THREE.DirectionalLight(0xffffff,.8);dl.position.set(5,10,7);mdlS.add(dl);mdlS.add(new THREE.GridHelper(30,30,0x666666,0x888888));mdlOr=new THREE.OrbitControls(mdlC,mdlR.domElement);mdlOr.target.set(0,1.5,0);mdlOr.enableDamping=true;mdlOr.minDistance=2;mdlOr.maxDistance=30;mdlOr.update();window.addEventListener('resize',function(){var w=vp.clientWidth,h=vp.clientHeight;if(!w||!h)return;mdlC.aspect=w/h;mdlC.updateProjectionMatrix();mdlR.setSize(w,h)});var lft2=performance.now();(function loop(t){requestAnimationFrame(loop);if(!modelEditorScreen.classList.contains('active'))return;var n=t||performance.now(),dt=Math.min(.05,(n-lft2)/1000);lft2=n;mdlOr.update();if(mdlGroup)applyModelAnim(mdlGroup,mdlAnimPreview,dt);mdlR.render(mdlS,mdlC)})()}
function mdlRenderScene(){if(mdlGroup)mdlS.remove(mdlGroup);mdlGroup=buildModelFromDef({parts:mdlParts});mdlS.add(mdlGroup)}
function mdlRenderList(){var list=document.getElementById('mdlPartList');if(!mdlParts.length){list.innerHTML='<div style="padding:10px;color:#5a6373;font-style:italic;text-align:center;font-size:12px">Нет частей</div>';return}var ico={box:'◼',sphere:'●',cylinder:'▮',cone:'▲'};var roleLb={head:'👤 голова',body:'🎽 тело',legL:'🦵 лев.нога',legR:'🦵 прав.нога',armL:'💪 лев.рука',armR:'💪 прав.рука',tail:'🐕 хвост',ear:'👂 ухо',eye:'👁 глаз',other:'▫ другое'};list.innerHTML=mdlParts.map(function(p,i){return '<div class="mdl-part-item'+(i===mdlSelIdx?' active':'')+'" data-i="'+i+'"><span>'+ico[p.shape]+'</span> '+(roleLb[p.role]||'часть')+'<button class="mdl-del" data-del="'+i+'">×</button></div>'}).join('');list.querySelectorAll('.mdl-part-item').forEach(function(el){el.onclick=function(e){if(e.target.classList.contains('mdl-del'))return;mdlSelIdx=parseInt(el.dataset.i);mdlRenderList();mdlRenderProps()}});list.querySelectorAll('[data-del]').forEach(function(b){b.onclick=function(e){e.stopPropagation();mdlParts.splice(parseInt(b.dataset.del),1);if(mdlSelIdx>=mdlParts.length)mdlSelIdx=mdlParts.length-1;mdlRenderScene();mdlRenderList();mdlRenderProps()}})}
function mdlRenderProps(){var c=document.getElementById('mdlPartProps');if(mdlSelIdx<0||!mdlParts[mdlSelIdx]){c.innerHTML='<p style="color:#5a6373;font-style:italic;font-size:12px;text-align:center;padding:12px">Выбери часть</p>';return}var p=mdlParts[mdlSelIdx];var roleLb={head:'👤 Голова',body:'🎽 Тело',legL:'🦵 Лев.нога',legR:'🦵 Прав.нога',armL:'💪 Лев.рука',armR:'💪 Прав.рука',tail:'🐕 Хвост',ear:'👂 Ухо',eye:'👁 Глаз',other:'▫ Другое'};var html='<div class="mdl-row"><label>🎯 Роль</label><select id="mpRole">';Object.keys(roleLb).forEach(function(k){html+='<option value="'+k+'"'+(p.role===k?' selected':'')+'>'+roleLb[k]+'</option>'});html+='</select></div>';html+='<div class="mdl-row"><label>Форма</label><select id="mpShape"><option value="box"'+(p.shape==='box'?' selected':'')+'>Куб</option><option value="sphere"'+(p.shape==='sphere'?' selected':'')+'>Сфера</option><option value="cylinder"'+(p.shape==='cylinder'?' selected':'')+'>Цилиндр</option><option value="cone"'+(p.shape==='cone'?' selected':'')+'>Конус</option></select></div>';html+='<div class="mdl-row"><label>Цвет</label><input type="color" id="mpColor" value="'+p.color+'"></div>';html+='<div class="mdl-row"><label>Позиция</label><div class="mdl-vec"><input type="number" id="mpPosX" step="0.1" value="'+p.pos[0].toFixed(2)+'"><input type="number" id="mpPosY" step="0.1" value="'+p.pos[1].toFixed(2)+'"><input type="number" id="mpPosZ" step="0.1" value="'+p.pos[2].toFixed(2)+'"></div></div>';html+='<div class="mdl-row"><label>Поворот</label><div class="mdl-vec"><input type="number" id="mpRotX" step="0.1" value="'+p.rot[0].toFixed(2)+'"><input type="number" id="mpRotY" step="0.1" value="'+p.rot[1].toFixed(2)+'"><input type="number" id="mpRotZ" step="0.1" value="'+p.rot[2].toFixed(2)+'"></div></div>';html+='<div class="mdl-row"><label>Размер</label><div class="mdl-vec"><input type="number" id="mpScaleX" step="0.1" value="'+p.scale[0].toFixed(2)+'"><input type="number" id="mpScaleY" step="0.1" value="'+p.scale[1].toFixed(2)+'"><input type="number" id="mpScaleZ" step="0.1" value="'+p.scale[2].toFixed(2)+'"></div></div>';html+='<div class="mdl-row"><label>Дублировать</label><button class="tbtn" id="mpDup" style="padding:4px 10px;font-size:11px">📋</button></div>';c.innerHTML=html;var upd=function(){p.role=document.getElementById('mpRole').value;p.shape=document.getElementById('mpShape').value;p.color=document.getElementById('mpColor').value;p.pos=[parseFloat(document.getElementById('mpPosX').value)||0,parseFloat(document.getElementById('mpPosY').value)||0,parseFloat(document.getElementById('mpPosZ').value)||0];p.rot=[parseFloat(document.getElementById('mpRotX').value)||0,parseFloat(document.getElementById('mpRotY').value)||0,parseFloat(document.getElementById('mpRotZ').value)||0];p.scale=[parseFloat(document.getElementById('mpScaleX').value)||.1,parseFloat(document.getElementById('mpScaleY').value)||.1,parseFloat(document.getElementById('mpScaleZ').value)||.1];mdlRenderScene();mdlRenderList()};['mpRole','mpShape','mpColor','mpPosX','mpPosY','mpPosZ','mpRotX','mpRotY','mpRotZ','mpScaleX','mpScaleY','mpScaleZ'].forEach(function(id){var el=document.getElementById(id);if(el)el.oninput=upd});document.getElementById('mpDup').onclick=function(){var copy=JSON.parse(JSON.stringify(p));copy.pos[0]+=.5;mdlParts.push(copy);mdlSelIdx=mdlParts.length-1;mdlRenderScene();mdlRenderList();mdlRenderProps()}}
function mdlAddPart(shape){mdlParts.push({role:'other',shape:shape,color:'#888888',pos:[0,1,0],rot:[0,0,0],scale:[1,1,1]});mdlSelIdx=mdlParts.length-1;mdlRenderScene();mdlRenderList();mdlRenderProps()}
function mdlLoadPreset(key){var p=MODEL_PRESETS[key];if(!p)return;mdlParts=JSON.parse(JSON.stringify(p.parts));mdlSelIdx=-1;document.getElementById('mdlName').value=p.name.replace(/^[^\s]+\s/,'')||'Модель';document.getElementById('mdlScript').value=p.script||'';document.getElementById('mdlIsPet').checked=!!p.isPet;document.getElementById('mdlPrice').value=p.price||0;mdlRenderScene();mdlRenderList();mdlRenderProps()}
function openModelEditor(id){var pres=document.getElementById('mdlPresets');pres.innerHTML='';Object.keys(MODEL_PRESETS).forEach(function(k){var b=document.createElement('button');b.className='mdl-preset';b.textContent=MODEL_PRESETS[k].name;b.onclick=function(){mdlLoadPreset(k)};pres.appendChild(b)});document.querySelectorAll('[data-addpart]').forEach(function(b){b.onclick=function(){mdlAddPart(b.dataset.addpart)}});document.getElementById('mdlAnimPreview').onchange=function(){mdlAnimPreview=this.value};if(id){var defs=getModelDefs();var def=defs.filter(function(d){return d.id===id})[0];if(def){mdlEditId=id;mdlParts=JSON.parse(JSON.stringify(def.parts||[]));document.getElementById('mdlName').value=def.name;document.getElementById('mdlScript').value=def.script||'';document.getElementById('mdlIsPet').checked=!!def.isPet;document.getElementById('mdlPrice').value=def.price||0}}else{mdlEditId=null;mdlParts=[];document.getElementById('mdlName').value='Моя модель';document.getElementById('mdlScript').value='api.chat("Привет!"); api.sound();';document.getElementById('mdlIsPet').checked=false;document.getElementById('mdlPrice').value=0}mdlSelIdx=-1;switchScr(modelEditorScreen);if(!mdlIn){mdlIn=true;setTimeout(function(){initMdlEditor();mdlRenderScene();mdlRenderList();mdlRenderProps()},50)}else{mdlRenderScene();mdlRenderList();mdlRenderProps()}}
document.getElementById('mdlExitBtn').onclick=function(){switchScr(editorScreen)};
document.getElementById('mdlSaveBtn').onclick=function(){var name=document.getElementById('mdlName').value.trim()||'Модель';var script=document.getElementById('mdlScript').value;var isPet=document.getElementById('mdlIsPet').checked;var price=parseInt(document.getElementById('mdlPrice').value)||0;if(!mdlParts.length){toast('Добавь хотя бы одну часть');return}var defs=getModelDefs();if(mdlEditId){for(var i=0;i<defs.length;i++)if(defs[i].id===mdlEditId){defs[i]={id:mdlEditId,name:name,parts:mdlParts,script:script,isPet:isPet,price:price};break}}else{defs.push({id:genId('mdl'),name:name,parts:mdlParts,script:script,isPet:isPet,price:price})}saveModelDefs(defs);toast('💾 Модель сохранена!');switchScr(editorScreen)};
document.getElementById('mdlLoadBtn').onclick=function(){var defs=getModelDefs();if(!defs.length){toast('Нет сохранённых моделей');return}var list=defs.map(function(d,i){return(i+1)+'. '+d.name+(d.isPet?' 🐾':'')}).join('\n');var sel=prompt('Выбери модель:\n'+list);if(!sel)return;var idx=parseInt(sel)-1;if(idx<0||idx>=defs.length)return;var d=defs[idx];mdlEditId=d.id;mdlParts=JSON.parse(JSON.stringify(d.parts||[]));document.getElementById('mdlName').value=d.name;document.getElementById('mdlScript').value=d.script||'';document.getElementById('mdlIsPet').checked=!!d.isPet;document.getElementById('mdlPrice').value=d.price||0;mdlSelIdx=-1;mdlRenderScene();mdlRenderList();mdlRenderProps();toast('📂 '+d.name)};
function addModelFromLibrary(){var defs=getModelDefs();if(!defs.length){toast('Библиотека пуста');return}var list=defs.map(function(d,i){return(i+1)+'. '+d.name+(d.isPet?' 🐾':'')}).join('\n');var sel=prompt('Какую модель добавить?\n'+list);if(!sel)return;var idx=parseInt(sel)-1;if(idx<0||idx>=defs.length){toast('Неверный номер');return}var d=defs[idx];var mesh=spawnFromDataPatched({type:'model',name:d.name,def:d,script:d.script||'',position:[0,0,0],rotation:[0,0,0],scale:[1,1,1]});if(mesh){selObj(mesh);renderExp();toast('✓ '+d.name)}}
document.getElementById('openModelEditorBtn').onclick=function(){openModelEditor(null)};
document.getElementById('addModelBtn').onclick=addModelFromLibrary;
document.getElementById('makeModelBtn').onclick=function(){if(!currentUser){alert('Войди');return}openModelEditor(null)};

