var activePets=[];
function spawnPetFromDef(def){if(!plS||!playPlayer)return;var g=buildModelFromDef(def);g.position.set(playPlayer.position.x+2+(Math.random()-.5)*2,0,playPlayer.position.z+2+(Math.random()-.5)*2);g.userData.type='model';g.userData.def=def;g.userData.isPet=true;g.userData.animTime=0;g.userData.animState='idle';plS.add(g);activePets.push(g);if(activePets.length>3){var old=activePets.shift();plS.remove(old)}chatMsg('*','🐾 '+def.name+' призван!',true)}
window.spawnPet=spawnPetFromDef;
function updateActivePets(dt){if(!playPlayer)return;activePets.forEach(function(pet){var dx=playPlayer.position.x-pet.position.x,dz=playPlayer.position.z-pet.position.z,dist=Math.sqrt(dx*dx+dz*dz);if(dist>3){pet.position.x+=(dx/dist)*4*dt;pet.position.z+=(dz/dist)*4*dt;pet.rotation.y=Math.atan2(dx,dz);pet.userData.animState='walk'}else if(dist>.8){pet.position.x+=(dx/dist)*2*dt;pet.position.z+=(dz/dist)*2*dt;pet.rotation.y=Math.atan2(dx,dz);pet.userData.animState='walk'}else{pet.rotation.y=playPlayer.rotation.y;pet.userData.animState='idle'}pet.position.y=0;applyModelAnim(pet,pet.userData.animState,dt)})}
document.getElementById('playPetBtn').onclick=function(){var owned=getMyShop().owned.filter(function(id){var c=findClothingById(id);return c&&c.type==='pet'});var defs=getModelDefs().filter(function(d){return d.isPet});if(!defs.length){chatMsg('*','В этой игре нет питомцев',true);return}var avail=defs.filter(function(d){var found=owned.some(function(id){var c=findClothingById(id);return c&&c.defId===d.id});return found||d.price===0});if(!avail.length){chatMsg('*','Ты не купил ни одного питомца. Иди в магазин!',true);return}var list=avail.map(function(d,i){return(i+1)+'. '+d.name}).join('\n');var sel=prompt('Какого питомца призвать?\n'+list);if(!sel)return;var idx=parseInt(sel)-1;if(idx<0||idx>=avail.length)return;spawnPetFromDef(avail[idx])};
window.openPetShop=function(){var defs=getModelDefs().filter(function(d){return d.isPet&&d.price>0});if(!defs.length){chatMsg('*','Магазин питомцев пуст',true);return}var owned=getMyShop().owned;var msg='🛒 МАГАЗИН ПИТОМЦЕВ\nБаланс: '+getBal()+' T\n\n';defs.forEach(function(d,i){var has=owned.some(function(id){var c=findClothingById(id);return c&&c.defId===d.id});msg+=(i+1)+'. '+d.name+' — '+d.price+' T '+(has?'✅':'')+'\n'});msg+='\nВведи номер, чтобы купить:';var sel=prompt(msg);if(!sel)return;var idx=parseInt(sel)-1;if(idx<0||idx>=defs.length)return;var d=defs[idx];if(owned.some(function(id){var c=findClothingById(id);return c&&c.defId===d.id})){chatMsg('*','Уже куплено!',true);return}if(getBal()<d.price){chatMsg('*','❌ Мало денег',true);return}setBal(getBal()-d.price);var cl=getMyClothes();cl.push({id:genId('petbuy'),type:'pet',defId:d.id,name:d.name,price:d.price,def:d,canvasData:'',created:new Date().toLocaleDateString('ru-RU')});saveMyClothes(cl);var s=getMyShop();s.owned.push(cl[cl.length-1].id);saveMyShop(s);updateBal();chatMsg('*','✅ Куплен: '+d.name,true);apiSound()};
function apiSound(){try{var a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=600;g.gain.value=.1;o.start();o.stop(a.currentTime+.1)}catch(e){}}

