var ha3D=false,haS,haC,haR,haCh,yaw=0;
function initHA(){var vp=document.getElementById('homeAvatarCanvas');if(!vp)return;while(vp.firstChild)vp.removeChild(vp.firstChild);haS=new THREE.Scene();haS.background=new THREE.Color(0xe1ecf9);var w=vp.clientWidth||160,h=vp.clientHeight||200;haC=new THREE.PerspectiveCamera(38,w/h,.1,50);haC.position.set(0,4,9);haC.lookAt(0,3,0);haR=new THREE.WebGLRenderer({antialias:true});haR.setPixelRatio(Math.min(devicePixelRatio,2));haR.setSize(w,h);vp.appendChild(haR.domElement);haS.add(new THREE.HemisphereLight(0xffffff,0x555555,.9));haS.add(new THREE.AmbientLight(0xffffff,.55));var dl=new THREE.DirectionalLight(0xffffff,.75);dl.position.set(5,10,7);haS.add(dl);haCh=buildChar();haS.add(haCh);applyClothes(haCh);(function loop(){requestAnimationFrame(loop);if(!homeScreen.classList.contains('active'))return;yaw+=.008;haCh.rotation.y=yaw;animChar(haCh,'idle',.016);haR.render(haS,haC)})()}
function refreshHA(){if(haCh)applyClothes(haCh)}
function renderHomeFriends(){var r=document.getElementById('homeFriendsRow');if(r)r.innerHTML='<div class="friend-tile"><span class="friend-nick" style="color:#0af">Приглашай друзей!</span></div>'}
function renderHomeGames(){var r=document.getElementById('homeGamesRow');if(!r)return;var gs=getAllGamesFlat();if(!gs.length){r.innerHTML='<div style="color:#888;font-style:italic;padding:10px">Пока нет игр</div>';return}r.innerHTML=gs.map(function(g){return '<div class="game-tile"><div class="game-thumb">'+esc((g.title||'?')[0].toUpperCase())+'</div><div class="game-title">'+esc(g.title)+'</div><div class="game-author">by '+esc(g.author)+'</div><button class="btn-play" data-pid="'+g.id+'">PLAY</button></div>'}).join('');r.querySelectorAll('[data-pid]').forEach(function(b){b.onclick=function(){startPlay(b.dataset.pid)}})}
function renderCreate(){var gs=getMyGames();document.getElementById('gamesCount').textContent=gs.length;var c=document.getElementById('gamesContainer');var html='';if(!gs.length)html='<div class="empty"><span class="num">0</span>У тебя ещё нет игр.</div>';else html=gs.map(function(g){return '<div class="game-card"><div class="thumb">'+esc((g.title||'?')[0].toUpperCase())+'</div><div class="gbody"><div class="gtitle">'+esc(g.title)+'</div><div class="gmeta">'+esc(g.created)+'</div><div class="card-actions"><button class="btn-edit" data-eid="'+g.id+'">Edit</button><button class="btn-delete" data-did="'+g.id+'">×</button></div></div></div>'}).join('');var cl=getMyClothes();if(cl.length)html+='<h2 style="margin-top:32px;grid-column:1/-1;color:#333;font-weight:900">👕 Мои вещи ('+cl.length+')</h2>'+cl.map(function(c){return '<div class="clothing-card"><div class="thumb"><img loading="lazy" src="'+(c.canvasData||'')+'"></div><div class="gbody"><div class="gtitle">'+esc(c.name)+'</div><div class="gprice">'+(c.price>0?'💰 '+c.price+' T':'🆓 Free')+(c.type==='pet'?' 🐾':'')+'</div><div class="card-actions"><button class="btn-edit" data-ceid="'+c.id+'">Edit</button><button class="btn-delete" data-cdid="'+c.id+'">×</button></div></div></div>'}).join('');c.innerHTML=html;c.querySelectorAll('[data-eid]').forEach(function(b){b.onclick=function(){openEditor(b.dataset.eid)}});c.querySelectorAll('[data-did]').forEach(function(b){b.onclick=function(){if(!confirm('?'))return;saveMyGames(getMyGames().filter(function(g){return g.id!==b.dataset.did}));renderCreate();renderHomeGames()}});c.querySelectorAll('[data-ceid]').forEach(function(b){b.onclick=function(){var c=findClothingById(b.dataset.ceid);if(c&&c.type==='hat')openHatEditor(b.dataset.ceid);else if(c&&c.type==='pet')toast('Питомец: '+c.name);else editClothing(b.dataset.ceid)}});c.querySelectorAll('[data-cdid]').forEach(function(b){b.onclick=function(){var id=b.dataset.cdid;if(!confirm('?'))return;saveMyClothes(getMyClothes().filter(function(x){return x.id!==id}));renderCreate()}})}
var shopCat='shirt';document.querySelectorAll('.shop-cat').forEach(function(b){b.onclick=function(){document.querySelectorAll('.shop-cat').forEach(function(x){x.classList.remove('active')});b.classList.add('active');shopCat=b.dataset.cat;renderShop()}});
function renderShop(){var g=document.getElementById('shopItemsGrid'),em=document.getElementById('shopEmpty');if(shopCat==='pet'){var defs=getModelDefs().filter(function(d){return d.isPet});if(!defs.length){g.innerHTML='';em.style.display='block';return}em.style.display='none';var owned=getMyShop().owned;g.innerHTML=defs.map(function(d){var has=owned.some(function(id){var c=findClothingById(id);return c&&c.defId===d.id});return '<div class="shop-item"><div style="height:140px;background:#87ceeb;display:flex;align-items:center;justify-content:center;font-size:48px">🐾</div><div class="gbody"><div class="gtitle">'+esc(d.name)+'</div><div class="gprice">'+(d.price>0?'💰 '+d.price+' T':'🆓 Free')+'</div><button class="btn-buy" data-buypet="'+d.id+'"'+(has?' disabled':'')+'>'+(has?'Куплено':'Купить')+'</button></div></div>'}).join('');g.querySelectorAll('[data-buypet]').forEach(function(b){b.onclick=function(){buyPet(b.dataset.buypet)}});return}
var ad=getClothesData(),items=[];Object.keys(ad).forEach(function(k){(ad[k]||[]).forEach(function(c){if((c.type||'shirt')===shopCat)items.push({a:k,cl:c})})});if(!items.length){g.innerHTML='';em.style.display='block';return}em.style.display='none';var s=getMyShop();g.innerHTML=items.map(function(x){var o=s.owned.indexOf(x.cl.id)>=0;return '<div class="shop-item"><div style="height:140px;background:#87ceeb;display:flex;align-items:center;justify-content:center"><img loading="lazy" src="'+(x.cl.canvasData||'')+'" style="max-width:100%;max-height:100%"></div><div class="gbody"><div class="gtitle">'+esc(x.cl.name)+'</div><div class="gprice">'+(x.cl.price>0?'💰 '+x.cl.price+' T':'🆓 Free')+'</div><button class="btn-buy" data-buy="'+x.cl.id+'"'+(o?' disabled':'')+'>'+(o?'Куплено':'Купить')+'</button></div></div>'}).join('');g.querySelectorAll('[data-buy]').forEach(function(b){b.onclick=function(){buyItem(b.dataset.buy)}})}
function buyPet(defId){var d=getModelDefs().filter(function(x){return x.id===defId})[0];if(!d)return;var owned=getMyShop().owned;if(owned.some(function(id){var c=findClothingById(id);return c&&c.defId===d.id})){toast('Уже куплено');return}if(d.price>getBal()){toast('Мало T');return}setBal(getBal()-d.price);var cl=getMyClothes();var newId=genId('petbuy');cl.push({id:newId,type:'pet',defId:d.id,name:d.name,price:d.price,def:d,canvasData:'',created:new Date().toLocaleDateString('ru-RU')});saveMyClothes(cl);var s=getMyShop();s.owned.push(newId);saveMyShop(s);updateBal();toast('✅ Куплен: '+d.name);apiSound();renderShop()}
function buyItem(id){var f=findClothingById(id);if(!f)return;var s=getMyShop();if(s.owned.indexOf(id)>=0){toast('Уже куплено');return}var b=getBal();if(f.price>0&&b<f.price){toast('Мало T');return}if(f.price>0)setBal(b-f.price);s.owned.push(id);saveMyShop(s);updateBal();toast('Куплено: '+f.name);renderShop()}
function showMsg(t,ty){message.textContent=t;message.className='message '+ty}
tabs.forEach(function(tb){tb.onclick=function(){tabs.forEach(function(t){t.classList.remove('active')});tb.classList.add('active');loginForm.classList.remove('active');registerForm.classList.remove('active');(tb.dataset.tab==='login'?loginForm:registerForm).classList.add('active');message.textContent=''}});
function switchScr(s){[authScreen,loadingScreen,homeScreen,editorScreen,playScreen,clothingTypeScreen,clothingEditorScreen,hatEditorScreen,modelEditorScreen].forEach(function(x){if(x)x.classList.remove('active')});s.classList.add('active')}
function loginOK(name){currentUser=name;document.getElementById('playerName').textContent=name;document.getElementById('myAvatarName').textContent=name;var su=document.getElementById('studioUser');if(su)su.textContent=name;switchScr(loadingScreen);setTimeout(function(){document.querySelectorAll('.nav-btn').forEach(function(b){b.classList.remove('active')});document.querySelector('.nav-btn[data-page="home"]').classList.add('active');document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active')});document.querySelector('.page[data-page-content="home"]').classList.add('active');renderCreate();renderHomeGames();renderHomeFriends();renderShop();updateBal();if(!ha3D){ha3D=true;setTimeout(initHA,80)}else refreshHA();switchScr(homeScreen)},600)}
registerForm.addEventListener('submit',function(e){e.preventDefault();var u=document.getElementById('regUsername').value.trim(),p=document.getElementById('regPassword').value,p2=document.getElementById('regPassword2').value;if(u.length<3)return showMsg('Имя мин.3','error');if(p.length<4)return showMsg('Пароль мин.4','error');if(p!==p2)return showMsg('Пароли разные','error');var us=getUsers();if(us[u.toLowerCase()])return showMsg('Имя занято','error');us[u.toLowerCase()]={username:u,password:p};saveUsers(us);registerForm.reset();document.querySelector('[data-tab="login"]').click();showMsg('Готово! Войди.','success')});
