document.querySelectorAll('.nav-btn[data-page]').forEach(function(b){b.onclick=function(){document.querySelectorAll('.nav-btn').forEach(function(x){x.classList.remove('active')});b.classList.add('active');var pg=b.dataset.page;document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active')});document.querySelector('.page[data-page-content="'+pg+'"]').classList.add('active');if(pg==='create')renderCreate();if(pg==='home'){renderHomeGames();renderHomeFriends();refreshHA()}if(pg==='shop'){renderShop();updateBal()}if(pg==='avatar')renderMyAv()}});
