document.getElementById('createGameBtn').onclick=function(){var t=prompt('Название:','My Game '+(getMyGames().length+1));if(!t)return;var c=t.trim();if(!c)return;var gs=getMyGames();gs.push({id:genId('g'),title:c,created:new Date().toLocaleDateString('ru-RU'),author:currentUser,parts:[],gui:[]});saveMyGames(gs);renderCreate();renderHomeGames()};

