var myIn=false,myS,myC,myR,myOr,myCh,myTab='shirt';
function initMy(){var vp=document.getElementById('myAvatarViewport');while(vp.firstChild)vp.removeChild(vp.firstChild);myS=new THREE.Scene();myS.background=new THREE.Color(0xd4e5f7);var w=vp.clientWidth||400,h=vp.clientHeight||520;myC=new THREE.PerspectiveCamera(42,w/h,.1,100);myC.position.set(-4,4.5,-10);myR=new THREE.WebGLRenderer({antialias:true});myR.setPixelRatio(Math.min(devicePixelRatio,2));myR.setSize(w,h);vp.appendChild(myR.domElement);myS.add(new THREE.HemisphereLight(0xffffff,0x555555,.9));myS.add(new THREE.AmbientLight(0xffffff,.55));var dl=new THREE.DirectionalLight(0xffffff,.75);dl.position.set(-6,10,-8);myS.add(dl);myCh=buildChar();myS.add(myCh);applyClothes(myCh);myOr=new THREE.OrbitControls(myC,myR.domElement);myOr.target.set(0,3,0);myOr.enableDamping=true;myOr.enablePan=false;myOr.minDistance=5;myOr.maxDistance=18;myOr.update();window.addEventListener('resize',function(){var w=vp.clientWidth,h=vp.clientHeight;if(!w||!h)return;myC.aspect=w/h;myC.updateProjectionMatrix();myR.setSize(w,h)});(function loop(){requestAnimationFrame(loop);var pg=document.querySelector('.page[data-page-content="avatar"]');if(!pg||!pg.classList.contains('active'))return;myOr.update();animChar(myCh,'idle',.016);myR.render(myS,myC)})()}
