function mkMats(p){var t=cTx[p],w=function(){return new THREE.MeshStandardMaterial({color:0xffffff,roughness:.85})};return[t.right?new THREE.MeshStandardMaterial({map:t.right,roughness:.85}):w(),t.left?new THREE.MeshStandardMaterial({map:t.left,roughness:.85}):w(),t.top?new THREE.MeshStandardMaterial({map:t.top,roughness:.85}):w(),t.bottom?new THREE.MeshStandardMaterial({map:t.bottom,roughness:.85}):w(),t.front?new THREE.MeshStandardMaterial({map:t.front,roughness:.85}):w(),t.back?new THREE.MeshStandardMaterial({map:t.back,roughness:.85}):w()]}
