function applyClTex(){if(!clM)return;var L=clM.userData.limbs,c=CLCON[clType];c.p.forEach(function(p){if(p==='head'){if(L.head)L.head.material=mkHead()}else{var m=L[p];if(m.isMesh)m.material=mkMats(p);else m.traverse(function(o){if(o.isMesh)o.material=mkMats(p)})}})}
function hexRgb(h){h=h.replace('#','');if(h.length===3)h=h.split('').map(function(c){return c+c}).join('');return{r:parseInt(h.substr(0,2),16),g:parseInt(h.substr(2,2),16),b:parseInt(h.substr(4,2),16)}}
function getPix(e){var r=ccv.getBoundingClientRect();return{x:Math.max(0,Math.min(31,Math.floor((e.clientX-r.left)/r.width*32))),y:Math.max(0,Math.min(31,Math.floor((e.clientY-r.top)/r.height*32)))}}
function paint(x,y){var cv=cSt[curP][curF],ctx=cv.getContext('2d');if(clT==='picker'){var p=ctx.getImageData(x,y,1,1).data;clColor='#'+[p[0],p[1],p[2]].map(function(v){return('0'+v.toString(16)).slice(-2)}).join('');document.getElementById('clothingColor').value=clColor;return}if(clT==='fill'){var img=ctx.getImageData(0,0,32,32),d=img.data,i0=(y*32+x)*4,tr=d[i0],tg=d[i0+1],tb=d[i0+2],f=hexRgb(clColor);if(tr===f.r&&tg===f.g&&tb===f.b)return;var st=[[x,y]],vis={};while(st.length){var pt=st.pop(),px=pt[0],py=pt[1];if(px<0||px>=32||py<0||py>=32)continue;var k=px+','+py;if(vis[k])continue;vis[k]=1;var i=(py*32+px)*4;if(d[i]!==tr||d[i+1]!==tg||d[i+2]!==tb)continue;d[i]=f.r;d[i+1]=f.g;d[i+2]=f.b;d[i+3]=255;st.push([px+1,py]);st.push([px-1,py]);st.push([px,py+1]);st.push([px,py-1])}ctx.putImageData(img,0,0)}else{ctx.fillStyle=clT==='eraser'?'#fff':clColor;ctx.fillRect(x,y,1,1)}redrawC();if(cTx[curP]&&cTx[curP][curF])cTx[curP][curF].needsUpdate=true}
ccv.addEventListener('pointerdown',function(e){e.preventDefault();var p=getPix(e);paint(p.x,p.y);clDraw=true});
ccv.addEventListener('pointermove',function(e){if(clDraw){var p=getPix(e);paint(p.x,p.y)}});
window.addEventListener('pointerup',function(){clDraw=false});
function initCl3D(){var vp=document.getElementById('clothingViewport');clS=new THREE.Scene();clS.background=new THREE.Color(0x9ac9e8);var w=vp.clientWidth||400,h=vp.clientHeight||400;clC=new THREE.PerspectiveCamera(45,w/h,.1,100);clC.position.set(0,4,10);clR=new THREE.WebGLRenderer({antialias:true});clR.setPixelRatio(Math.min(devicePixelRatio,2));clR.setSize(w,h);vp.appendChild(clR.domElement);clS.add(new THREE.HemisphereLight(0xffffff,0x666666,.9));clS.add(new THREE.AmbientLight(0xffffff,.5));var dl=new THREE.DirectionalLight(0xffffff,.6);dl.position.set(5,10,7);clS.add(dl);clM=buildChar();clS.add(clM);refreshTx();applyClTex();clOr=new THREE.OrbitControls(clC,clR.domElement);clOr.target.set(0,3,0);clOr.enableDamping=true;clOr.enablePan=false;clOr.minDistance=5;clOr.maxDistance=18;clOr.update();window.addEventListener('resize',function(){var w=vp.clientWidth,h=vp.clientHeight;if(!w||!h)return;clC.aspect=w/h;clC.updateProjectionMatrix();clR.setSize(w,h)});(function loop(){requestAnimationFrame(loop);if(!clothingEditorScreen.classList.contains('active'))return;clOr.update();animChar(clM,'idle',.016);clR.render(clS,clC)})()}
function serParts(){var o={};CLP.forEach(function(p){o[p]={};CLF.forEach(function(f){o[p][f]=cSt[p][f].toDataURL('image/png')})});return o}
function loadParts(parts){if(!parts)return;CLP.forEach(function(p){if(!parts[p])return;CLF.forEach(function(f){if(!parts[p][f])return;var i=new Image();i.onload=function(){var ctx=cSt[p][f].getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,32,32);ctx.drawImage(i,0,0,32,32);refreshTx();if(p===curP&&f===curF)redrawC()};i.src=parts[p][f]})})}
function resetCl(){CLP.forEach(function(p){CLF.forEach(function(f){var ctx=cSt[p][f].getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,32,32)})});refreshTx();applyClTex()}
function openClEditor(t){clType=t;document.getElementById('clothingTitleType').textContent=CLCON[t].t;currentEditingClothing=null;document.getElementById('clothingName').value='My '+CLCON[t].t;document.getElementById('clothingPrice').value='0';buildClTabs();initCl();switchScr(clothingEditorScreen);if(!clIn){clIn=true;setTimeout(function(){initCl3D();redrawC()},60)}else{resetCl();redrawC()}}
function editClothing(id){var c=getMyClothes().filter(function(x){return x.id===id})[0];if(!c)return;currentEditingClothing=c;clType=c.type||'shirt';document.getElementById('clothingTitleType').textContent=CLCON[clType].t;document.getElementById('clothingName').value=c.name;document.getElementById('clothingPrice').value=c.price;buildClTabs();initCl();switchScr(clothingEditorScreen);if(!clIn){clIn=true;setTimeout(function(){initCl3D();loadParts(c.parts);redrawC()},80)}else{resetCl();loadParts(c.parts);redrawC()}}
document.getElementById('clothingClearBtn').onclick=function(){if(!confirm('?'))return;var ctx=cSt[curP][curF].getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,32,32);redrawC();if(cTx[curP]&&cTx[curP][curF])cTx[curP][curF].needsUpdate=true};
document.getElementById('clothingSaveBtn').onclick=function(){var n=document.getElementById('clothingName').value.trim()||'My '+CLCON[clType].t,p=parseInt(document.getElementById('clothingPrice').value)||0;if(p<0)p=0;var pd=serParts(),pv=pd[CLP[0]]&&pd[CLP[0]][CLF[0]]?pd[CLP[0]][CLF[0]]:'';var cl=getMyClothes();if(currentEditingClothing){for(var i=0;i<cl.length;i++)if(cl[i].id===currentEditingClothing.id){cl[i].name=n;cl[i].price=p;cl[i].type=clType;cl[i].parts=pd;cl[i].canvasData=pv;break}}else cl.push({id:genId('cl'),type:clType,name:n,price:p,parts:pd,canvasData:pv,created:new Date().toLocaleDateString('ru-RU')});saveMyClothes(cl);toast(CLCON[clType].t+' сохранён!')};
document.getElementById('clothingExitBtn').onclick=function(){switchScr(homeScreen);document.querySelectorAll('.nav-btn').forEach(function(b){b.classList.remove('active')});document.querySelector('.nav-btn[data-page="create"]').classList.add('active');document.querySelectorAll('.page').forEach(function(p){p.classList.remove('active')});document.querySelector('.page[data-page-content="create"]').classList.add('active');renderCreate()};

