(function(){var hud=document.querySelector('#playViewport .play-hud');if(hud){var p=document.createElement('div');p.className='interact-prompt';p.id='interactPrompt';p.textContent='Нажми E';hud.appendChild(p)}})();
setInterval(function(){var p=document.getElementById('interactPrompt');if(!p)return;if(!playScreen.classList.contains('active')||!playPlayer||!plPG){p.classList.remove('show');window._interactTarget=null;return}var nearest=null,nearDist=5;plPG.children.forEach(function(c){if(!c.userData)return;var ty=c.userData.type;if(ty!=='model'&&ty!=='part')return;if(!c.userData.script)return;var dx=playPlayer.position.x-c.position.x,dy=playPlayer.position.y-c.position.y,dz=playPlayer.position.z-c.position.z;var d=Math.sqrt(dx*dx+dy*dy+dz*dz);if(d<nearDist){nearDist=d;nearest=c}});if(nearest){p.textContent='🖐 Нажми E — '+(nearest.userData.name||'объект');p.classList.add('show');window._interactTarget=nearest}else{p.classList.remove('show');window._interactTarget=null}},150);
window.addEventListener('keydown',function(e){if(!playScreen.classList.contains('active'))return;if(e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA')return;if(e.key.toLowerCase()!=='e')return;var t=window._interactTarget;if(!t)return;var script=(t.userData.def&&t.userData.def.script)||t.userData.script||'';if(!script){chatMsg('*','У объекта нет скрипта',true);return}SCRIPT_API=makeScriptAPI(plPG.children,playPlayer);runScript(script,{part:t,player:playPlayer,parts:plPG.children,scene:plS})});

